            if (!seen_counter[counter[i]]) {
                print "    \"" counter[i] "\","
            }
        }
        mode = ""
        closed_counters = 1
    }
    print
}
END {
    if (!found_histograms || !closed_histograms || !found_counters || !closed_counters) {
        exit 2
    }
}
' "$metrics_file" > "$tmp"

mv "$tmp" "$metrics_file"
trap - EXIT

